from pathlib import Path
import json
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';lines=(r/'docs/replica/source/original.js').read_text().splitlines();starts=('const esc=','const icons=','const icon=','const t=','const btn=','const notice=','const categoryDefs=','const catName=','function openModal(','function closeModal(');defs='\n'.join(s for s in lines if s.startswith(starts));cases=[]
